import{_ as i,c as e,b as a,d as r,e as p,a as t,w as m,r as o,o as h,f as l}from"./app-BC3GIMfQ.js";const c="/assets/image1-C8wxYC5u.png",g="/assets/algo1-CyQ7WChF.png",d="/assets/image2-DNoYRb6s.png",u="/assets/image3-_YrNVhm4.png",x="/assets/image4-De8uNzQ0.png",w="/assets/table1-DoPy4UtM.png",y="/assets/table2-UnRwSJLm.png",v="/assets/algo2-DCh5RHRv.png",k="/assets/table3-CsUcl2Vo.png",b="/assets/image5-D-Sf_XXd.png",M="/assets/table4-C0HHHrnA.png",N="/assets/image6-CB0JHDm8.png",P="/assets/image7-D2gUV4JR.png",U="/assets/table5-CCTW9y3M.png",_={},f={class:"table-of-contents"};function z(A,s){const n=o("router-link");return h(),e("div",null,[s[20]||(s[20]=a("h1",{id:"pilotann-针对向量搜索的内存受限-gpu-加速",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#pilotann-针对向量搜索的内存受限-gpu-加速"},[a("span",null,"PilotANN: 针对向量搜索的内存受限 GPU 加速")])],-1)),r(" more "),s[21]||(s[21]=p('<div class="hint-container info"><p class="hint-container-title">相关信息</p><p><strong>论文题目</strong>: PilotANN: Memory-Bounded GPU Acceleration for Vector Search<br><strong>论文作者</strong>: Yuntao Gui, Peiqi Yin, Xiao Yan, Chaorui Zhang, Weixi Zhang, James Cheng<br><strong>作者单位</strong>: The Chinese University of Hong Kong, Huawei Technologies Co. Ltd.<br><strong>论文代码</strong>: <a href="https://github.com/ytgui/PilotANN" target="_blank" rel="noopener noreferrer">https://github.com/ytgui/PilotANN</a><br><strong>一句话解读</strong>: PilotANN 是一个混合 CPU-GPU 的 ANNS 框架，它通过在 GPU 上利用降维向量和小子图进行快速粗略搜索（“Pilot”），然后在 CPU 上利用全量数据进行精确精炼，从而解决了 GPU 显存不足以容纳大规模数据集的问题，实现了低成本高性能的向量搜索。</p></div>',1)),a("nav",f,[a("ul",null,[a("li",null,[t(n,{to:"#摘要"},{default:m(()=>s[0]||(s[0]=[l("摘要")])),_:1,__:[0]})]),a("li",null,[t(n,{to:"#_1-引言"},{default:m(()=>s[1]||(s[1]=[l("1. 引言")])),_:1,__:[1]})]),a("li",null,[t(n,{to:"#_2-背景"},{default:m(()=>s[2]||(s[2]=[l("2. 背景")])),_:1,__:[2]}),a("ul",null,[a("li",null,[t(n,{to:"#_2-1-anns-方法"},{default:m(()=>s[3]||(s[3]=[l("2.1. ANNS 方法")])),_:1,__:[3]})]),a("li",null,[t(n,{to:"#_2-2-重温图遍历"},{default:m(()=>s[4]||(s[4]=[l("2.2. 重温图遍历")])),_:1,__:[4]})])])]),a("li",null,[t(n,{to:"#_3-概述"},{default:m(()=>s[5]||(s[5]=[l("3. 概述")])),_:1,__:[5]})]),a("li",null,[t(n,{to:"#_4-gpu-领航-一种混合方法"},{default:m(()=>s[6]||(s[6]=[l("4. GPU 领航：一种混合方法")])),_:1,__:[6]}),a("ul",null,[a("li",null,[t(n,{to:"#_4-1-anns-的多阶段处理"},{default:m(()=>s[7]||(s[7]=[l("4.1. ANNS 的多阶段处理")])),_:1,__:[7]})]),a("li",null,[t(n,{to:"#_4-2-理解性能"},{default:m(()=>s[8]||(s[8]=[l("4.2. 理解性能")])),_:1,__:[8]})]),a("li",null,[t(n,{to:"#_4-3-方法细节"},{default:m(()=>s[9]||(s[9]=[l("4.3. 方法细节")])),_:1,__:[9]})])])]),a("li",null,[t(n,{to:"#_5-快速入口选择"},{default:m(()=>s[10]||(s[10]=[l("5. 快速入口选择")])),_:1,__:[10]})]),a("li",null,[t(n,{to:"#_6-评估"},{default:m(()=>s[11]||(s[11]=[l("6. 评估")])),_:1,__:[11]}),a("ul",null,[a("li",null,[t(n,{to:"#_6-1-实验设置"},{default:m(()=>s[12]||(s[12]=[l("6.1. 实验设置")])),_:1,__:[12]})]),a("li",null,[t(n,{to:"#_6-2-整体性能"},{default:m(()=>s[13]||(s[13]=[l("6.2. 整体性能")])),_:1,__:[13]})]),a("li",null,[t(n,{to:"#_6-3-组件分析"},{default:m(()=>s[14]||(s[14]=[l("6.3. 组件分析")])),_:1,__:[14]})])])]),a("li",null,[t(n,{to:"#_7-相关工作"},{default:m(()=>s[15]||(s[15]=[l("7. 相关工作")])),_:1,__:[15]}),a("ul",null,[a("li",null,[t(n,{to:"#_7-1-大规模-anns"},{default:m(()=>s[16]||(s[16]=[l("7.1. 大规模 ANNS")])),_:1,__:[16]})]),a("li",null,[t(n,{to:"#_7-2-gpu-加速-anns"},{default:m(()=>s[17]||(s[17]=[l("7.2. GPU 加速 ANNS")])),_:1,__:[17]})])])]),a("li",null,[t(n,{to:"#_8-结论"},{default:m(()=>s[18]||(s[18]=[l("8. 结论")])),_:1,__:[18]}),a("ul",null,[a("li",null,[t(n,{to:"#影响陈述"},{default:m(()=>s[19]||(s[19]=[l("影响陈述")])),_:1,__:[19]})])])])])]),s[22]||(s[22]=p('<h2 id="摘要" tabindex="-1"><a class="header-anchor" href="#摘要"><span>摘要</span></a></h2><ul><li>近似最近邻搜索（ANNS）已成为现代深度学习应用的基础，特别是通过集成到处理日益复杂的数据集和更高向量维度的生成式模型中而获得了极大的重视。现有的纯 CPU 解决方案，即使是最高效的基于图的方法，也难以满足这些不断增长的计算需求，而纯 GPU 解决方案则面临内存限制。作为解决方案，我们提出了 PilotANN，这是一个用于基于图的 ANNS 的混合 CPU-GPU 系统，利用了 CPU 丰富的 RAM 和 GPU 的并行处理能力。我们的方法将 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 搜索的图遍历过程分解为三个阶段：使用 SVD 降维向量的 GPU 加速子图遍历、CPU 精炼以及使用完整向量的精确搜索。此外，我们引入了快速入口选择（Fast Entry Selection）来改进搜索起点，同时最大化 GPU 利用率。实验结果表明，PilotANN 在 1 亿规模的数据集上实现了 3.9-5.4 倍的吞吐量加速，并且能够处理比 GPU 内存大 12 倍的数据集。我们提供了 PilotANN 的完整开源实现：<a href="https://github.com/ytgui/PilotANN" target="_blank" rel="noopener noreferrer">https://github.com/ytgui/PilotANN</a>。</li></ul><h2 id="_1-引言" tabindex="-1"><a class="header-anchor" href="#_1-引言"><span>1. 引言</span></a></h2><ul><li><p>近似最近邻搜索（ANNS）是一种基本的向量搜索技术，它可以有效地识别高维向量空间中的相似项。给定一个查询向量，ANNS 通过在准确性和搜索速度之间进行受控权衡来返回其 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span>-最近邻。这种准确性和速度之间的平衡使 ANNS 成为大规模相似性搜索问题的事实上的解决方案，在这些问题中，精确的最近邻计算在计算上是不可行的。传统上，ANNS 是检索引擎（Kulis &amp; Grauman, 2009; Gordo et al., 2016）和推荐系统（Covington et al., 2016; He et al., 2017; Yang et al., 2020）的骨干。最近，ANNS 通过集成到生成式 AI 系统中再次获得重视，它增强了真实性和效率，例如检索增强生成（Lewis et al., 2020; Blattmann et al., 2022）和语义缓存（Bang, 2023）。</p></li><li><p>随着生成式 AI 的最新进展，ANNS 的计算需求持续增长，特别是随着现代基于 Transformer 的架构处理更高维的嵌入和更大规模的数据集（Devlin et al., 2018; Dosovitskiy et al., 2021; Radford et al., 2021）。虽然深度学习系统由于其无状态性质可以轻松复制和水平扩展，但 ANNS 通常保持集中式，使单机吞吐量成为关键瓶颈。使用维度范围从 96 到 768 的 1 亿规模数据集，我们观察到 HNSW（Malkov &amp; Yashunin, 2020）的最先进 CPU 实现难以随着向量维度的增加保持高查询吞吐量（图 1）。具体而言，对于具有 768 维向量的 LAION 数据集，纯 CPU HNSW 每秒只能处理 2.1K 个查询（QPS）。这种低吞吐量对于需要处理数千个并发请求同时保持高处理吞吐量的生产服务来说尤其成问题。</p></li><li><p><img src="'+c+'" alt="image1" loading="lazy"></p></li><li><p>此前提高基于图的 ANNS 效率的尝试探索了几种方法。一个方向集中于开发细粒度的图构建方法（Fu et al., 2019; Lu et al., 2021）。虽然这些方法提高了搜索效率，但它们通常在构建阶段需要密集的计算资源，并且在大规模数据集方面面临可扩展性挑战（Chen et al., 2021）。另一种方法采用量化技术（Jégou et al., 2011a; Zhou et al., 2012; Douze et al., 2018）来压缩向量表示，减少内存占用和计算成本。然而，量化不可避免地会引入精度下降，呈现出搜索精度的根本权衡。</p></li><li><p>GPU 加速代表了增强 ANNS 性能的一个有前途的方向（Zhao et al., 2020; Zhu, 2022; Ootomo et al., 2023）。然而，尽管 GPU 具有巨大的并行处理能力，但利用它们并非易事。主要的限制是 GPU 内存容量，这限制了可以处理的数据集的大小。NVIDIA 最先进的基于 GPU 的 ANNS 库 CAGRA（Ootomo et al., 2023）需要具有大内存容量的昂贵 GPU 硬件（例如 A100）来处理中等规模的数据集。虽然统一虚拟内存（UVM）已被探索作为内存限制的解决方案，但之前的工作表明其在非图 ANNS 中无效（Zhang et al., 2024）。基于图的 ANNS 由于其动态性质和不规则的内存访问模式（见 §2.2），带来了额外的挑战，使得有效的 GPU 利用特别困难。</p></li><li><p>这些限制创造了对一种能够有效利用 CPU 和 GPU 能力的混合方法的明确需求。作为回应，我们提出了 PilotANN，这是一个针对基于图的 ANNS 的混合系统，旨在利用 GPU 的并行处理能力和 CPU 上可用的丰富 RAM。我们的方法专门解决了两个基本挑战：</p><ul><li><strong>C1：GPU 内存边界。</strong> GPU 的有限内存容量，通常在几十 GB，明显小于 CPU 的内存容量（可以超过数百 GB），从而限制了 ANNS 在 GPU 上的适用性。</li><li><strong>C2：有限的计算密度。</strong> GPU 针对复杂的矩阵-矩阵运算（例如 GEMM）进行了优化，但 ANNS 主要依赖于更简单的成对距离计算，导致 GPU 上的计算密度较低。</li></ul></li><li><p>PilotANN 通过两项关键创新解决了这些挑战。首先，我们引入了<strong>多阶段 ANNS 处理</strong>（§4），它将计算密集的 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 搜索问题分解为互补的组件：利用 GPU 功率在较小的子图上高效识别候选项，然后在 CPU 上进行细化和精确遍历，此时 ANNS 的复杂性显着降低。其次，我们开发了<strong>快速入口选择</strong>（§5），这是一种新颖的方法，可提供高质量的搜索入口点，从而提高 GPU 上的计算密度。我们在仅使用一张 NVIDIA A10 GPU（24 GB）的情况下进行的实验评估显示了显着的性能提升。我们在处理比 GPU 内存容量大 12 倍的数据集和图索引的同时，实现了 top-10 搜索吞吐量 3.9 - 5.4 倍的加速。</p></li><li><p>这项工作的贡献有三点：</p><ul><li>我们引入了一种新颖的混合架构，有效地实现了 CPU 基础 ANNS 的 GPU 加速。</li><li>我们开发了快速入口选择，这是一种用于优化入口点选择的 GPU 高效方法。</li><li>我们提供了 PilotANN 在真实世界数据集上有效性的全面经验证据。</li></ul></li></ul><h2 id="_2-背景" tabindex="-1"><a class="header-anchor" href="#_2-背景"><span>2. 背景</span></a></h2><ul><li>在本部分中，我们介绍 ANNS 和图遍历算法的基础知识，以便于后续讨论。</li></ul><h3 id="_2-1-anns-方法" tabindex="-1"><a class="header-anchor" href="#_2-1-anns-方法"><span>2.1. ANNS 方法</span></a></h3><ul><li><p>ANNS 的目标是根据距离度量（Chen et al., 2021; Peng et al., 2023; Douze et al., 2024）高效地找到给定数据集 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">X</span></span></span></span> 中最接近查询点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi></mrow><annotation encoding="application/x-tex">q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span></span></span></span> 的数据点。现代 ANNS 方法大致可分为两种主要方法：基于粗略聚类的非图方法，以及依赖于细粒度图连接性的基于图的方法。</p></li><li><p><em>传统的非图方法</em>采用粗略聚类作为其基本原则，划分搜索空间以减少查询期间的计算复杂度。这包括像空间划分 KD 树（Silpa-Anan &amp; Hartley, 2008）这样的技术，它递归地将空间划分为层次区域，以及局部敏感哈希（Gionis et al., 1999），它将相似的向量分组到桶中。聚类最直接的应用是倒排文件（IVF）方法（Jégou et al., 2011b），它显式地使用 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span>-means 将向量划分到倒排列表中。像 IMI（Babenko &amp; Lempitsky, 2015）这样的高级变体采用乘积聚类来创建更精细的分区，而 IVFADC（Schütze et al., 2008; Jégou et al., 2011a）将聚类与残差量化相结合。然而，这些粗略聚类方法在搜索复杂度和分区粒度之间面临着固有的权衡。</p></li><li><p><em>基于图的方法</em>采用一种根本不同的方法，即构建可导航的图结构（Hajebi et al., 2011; Malkov et al., 2014），其中每个数据点表示为一个节点，边连接相邻节点。在搜索过程中，这些方法执行图遍历以快速定位最近邻居。像 HNSW（Malkov &amp; Yashunin, 2020）这样的现代方法将邻近图组织成多层以进行由粗到细的搜索，而 NSG（Fu et al., 2019）优化图连接性以获得更好的搜索路径。研究一致表明，就准确性-吞吐量权衡而言，基于图的方法实现了最先进的性能，需要比传统的粗略聚类方法更少的距离计算就能达到相同的召回率（Douze et al., 2018; Chen et al., 2021）。这种卓越的性能源于它们捕获细粒度邻域连接和执行引导图遍历的能力，这使得基于图的方法高度优化。探索基于图的方法的进一步改进仍然是一个活跃的研究领域（Zhao et al., 2020; Ootomo et al., 2023; Karthik et al., 2024）。</p></li></ul><h3 id="_2-2-重温图遍历" tabindex="-1"><a class="header-anchor" href="#_2-2-重温图遍历"><span>2.2. 重温图遍历</span></a></h3><ul><li><p>基于图的 ANNS 通常采用启发式贪婪搜索算法 1。该算法通过每步维护有限数量的最有希望的候选解来有效地探索图，从而限制计算复杂度。</p></li><li><p><img src="'+g+'" alt="algo1" loading="lazy"></p></li><li><p>算法首先构建一个包含在搜索过程中识别出的最有希望解决方案的候选列表 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07153em;">C</span></span></span></span>（第 3 行）。该列表包含 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>e</mi><mi>f</mi></mrow><annotation encoding="application/x-tex">ef</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span></span></span></span> 个候选项，从中可以稍后获得 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 结果 (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mo>≤</mo><mi>e</mi><mi>f</mi></mrow><annotation encoding="application/x-tex">k \\le ef</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8304em;vertical-align:-0.136em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span></span></span></span>)。这里的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>e</mi><mi>f</mi></mrow><annotation encoding="application/x-tex">ef</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span></span></span></span> 作为控制搜索精度和速度的参数。在每个后续迭代中，搜索通过扩展 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07153em;">C</span></span></span></span> 中最佳未检查的候选项开始（第 5-6 行），计算未访问的相邻节点到查询向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi></mrow><annotation encoding="application/x-tex">q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span></span></span></span> 的距离（第 8 行），并将 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07153em;">C</span></span></span></span> 更新为潜在解决方案（第 9 行）。这个迭代过程持续进行，直到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07153em;">C</span></span></span></span> 中的所有节点都被检查过（第 4 行），表明在当前搜索空间内不可能有进一步的改进。</p></li><li><p>贪婪搜索算法表现出两个关键特征。首先，在每个邻居扩展迭代中，算法从动态变化的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07153em;">C</span></span></span></span> 中选择最佳候选者，使得遍历路径不可预测。这种具有 <strong>C1</strong> 的动态性质激发了大部分系统设计。其次，算法主要执行向量到向量的距离计算（第 8 行），这是简单的逐元素操作，无法利用 GPU 的矩阵乘法（GEMM）能力，即 <strong>C2</strong>。</p></li></ul><h2 id="_3-概述" tabindex="-1"><a class="header-anchor" href="#_3-概述"><span>3. 概述</span></a></h2><ul><li><p>PilotANN 采用了一种独特的混合 CPU-GPU 处理范式，利用了两种硬件的独特优势。图 2 说明了系统的架构和核心组件。</p></li><li><p><img src="'+d+'" alt="image2" loading="lazy"></p></li><li><p>PilotANN 的关键见解是将 ANNS 过程分解为在 GPU 和 CPU 上运行的互补阶段。在预处理期间，给定完整索引 ⓐ，我们采样一个较小的子图 ⓑ 并生成紧凑的向量表示 ⓒ。较小的子图和紧凑向量可以放入 GPU 内存，而原始的完整索引保留在 CPU RAM 中。在运行时，PilotANN 通过我们的多阶段处理方法（§4）处理查询，其中 GPU 阶段 ① 能够进行高效的初始探索，而 CPU 阶段 ② ③ 受益于降低的搜索复杂度。此外，快速入口选择（FES §5）旨在提高初始起点选择的质量和速度。总之，PilotANN 能够实现高吞吐量，同时有效地处理显着超过 GPU 内存容量的数据集。</p></li></ul><h2 id="_4-gpu-领航-一种混合方法" tabindex="-1"><a class="header-anchor" href="#_4-gpu-领航-一种混合方法"><span>4. GPU 领航：一种混合方法</span></a></h2><h3 id="_4-1-anns-的多阶段处理" tabindex="-1"><a class="header-anchor" href="#_4-1-anns-的多阶段处理"><span>4.1. ANNS 的多阶段处理</span></a></h3><ul><li><p>PilotANN 通过“分阶段数据准备处理”范式引入了一种新颖的向量搜索方法。与遵循“移动数据进行计算”模型的传统 GPU 赋能系统不同，我们的方法通过确保跨处理阶段的数据准备就绪来最小化数据移动。这种设计选择尤其关键，因为 §2.2 中显示的图遍历算法的固有特性。在迭代邻居扩展期间，搜索路径变得依赖于数据且不可预测，这在传统架构中将需要通过 PCIe 进行密集的数据传输。</p></li><li><p>我们的方法将搜索分解为三个不同的阶段：(i) 使用子图和简化向量的 GPU 领航，(ii) 使用子图和完整向量的残差精炼，以及 (iii) 使用完整图和向量的最终遍历。从查询和入口点开始，系统依次执行这些阶段以定位 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 匹配结果。</p></li><li><p><strong>① GPU 领航（GPU piloting）。</strong> 在第一阶段，我们采用降维和图采样来在内存限制下启用基于 GPU 的遍历。对于降维，我们对原始向量应用奇异值分解（SVD）：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mi>U</mi><mi mathvariant="normal">Σ</mi><msup><mi>V</mi><mi>T</mi></msup></mrow><annotation encoding="application/x-tex">X = U\\Sigma V^T</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">X</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">U</span><span class="mord">Σ</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.13889em;">T</span></span></span></span></span></span></span></span></span></span></span>，其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>V</mi><mi>T</mi></msup><mi>V</mi><mo>=</mo><mi>I</mi></mrow><annotation encoding="application/x-tex">V^T V = I</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.13889em;">T</span></span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">I</span></span></span></span> 确保变换的正交性，保留欧几里得距离。每个向量分解为两个分量：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover accent="true"><mi>x</mi><mo>^</mo></mover><mo>=</mo><mo stretchy="false">{</mo><msub><mi>x</mi><mrow><mi>p</mi><mi>r</mi><mi>i</mi><mi>m</mi><mi>a</mi><mi>r</mi><mi>y</mi></mrow></msub><mo separator="true">,</mo><msub><mi>x</mi><mrow><mi>r</mi><mi>e</mi><mi>s</mi><mi>i</mi><mi>d</mi><mi>u</mi><mi>a</mi><mi>l</mi></mrow></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\hat{x} = \\{x_{primary}, x_{residual}\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">x</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.02778em;">r</span><span class="mord mathnormal mtight">ima</span><span class="mord mathnormal mtight" style="margin-right:0.03588em;">ry</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">res</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.01968em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>x</mi><mrow><mi>p</mi><mi>r</mi><mi>i</mi><mi>m</mi><mi>a</mi><mi>r</mi><mi>y</mi></mrow></msub><mo>=</mo><mo stretchy="false">{</mo><msub><mi>U</mi><mrow><mn>1</mn><mo separator="true">,</mo><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mo separator="true">,</mo><mi>d</mi></mrow></msub><msub><mi mathvariant="normal">Σ</mi><mrow><mn>1</mn><mo separator="true">,</mo><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mo separator="true">,</mo><mi>d</mi></mrow></msub><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">x_{primary} = \\{U_{1,...,d}\\Sigma_{1,...,d}\\}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.02778em;">r</span><span class="mord mathnormal mtight">ima</span><span class="mord mathnormal mtight" style="margin-right:0.03588em;">ry</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.10903em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mpunct mtight">,</span><span class="mord mtight">...</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">Σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mpunct mtight">,</span><span class="mord mtight">...</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> 捕获具有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>d</mi></mrow><annotation encoding="application/x-tex">d</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">d</span></span></span></span> 个最高奇异值的主成分，而 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>x</mi><mrow><mi>r</mi><mi>e</mi><mi>s</mi><mi>i</mi><mi>d</mi><mi>u</mi><mi>a</mi><mi>l</mi></mrow></msub></mrow><annotation encoding="application/x-tex">x_{residual}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">res</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.01968em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 包含剩余分量。图采样过程采用均匀的节点采样来选择种子节点，然后进行 1-hop 邻居扩展以包括前沿节点，直到达到目标采样率；然后使用与原始索引相同的图构建算法重新连接采样的节点。</p></li><li><p><strong>② 残差精炼（Residual refinement）。</strong> 这个中间阶段通过结合 ① 中先前省略的残差向量分量来增强 GPU 结果。对于在 ① 中识别出的每个候选者，我们通过将 GPU 计算的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>x</mi><mrow><mi>p</mi><mi>r</mi><mi>i</mi><mi>m</mi><mi>a</mi><mi>r</mi><mi>y</mi></mrow></msub></mrow><annotation encoding="application/x-tex">x_{primary}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.02778em;">r</span><span class="mord mathnormal mtight">ima</span><span class="mord mathnormal mtight" style="margin-right:0.03588em;">ry</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 距离与 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>x</mi><mrow><mi>r</mi><mi>e</mi><mi>s</mi><mi>i</mi><mi>d</mi><mi>u</mi><mi>a</mi><mi>l</mi></mrow></msub></mrow><annotation encoding="application/x-tex">x_{residual}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">res</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.01968em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 距离相结合来计算完整距离。然后该阶段在子图上执行有限的图遍历（2 次迭代），根据其全维距离对候选者进行重新排序并生成已访问表。这个精炼过程产生了两个关键输出：更准确排名的候选者和指导后续完整图探索的访问历史。</p></li><li><p><strong>③ 最终遍历（Final traversal）。</strong> 最后阶段使用全维向量执行完整的图搜索，确搜索质量和完整性。基于前几个阶段的输出，它以两个关键优势进行传统的贪婪搜索算法 §2.2：预填充的已访问表和高质量的初始候选者。通过重用已访问表，搜索避免了重新访问先前探索过的节点。从早期阶段获得的起点的质量显着提高了遍历效率，见 §4.2。</p></li><li><p><strong>总结。</strong> 我们的设计具有成本效益，因为它只需要单个 GPU，同时可以很好地扩展到不同的向量维度和图复杂度。数据传输开销很小——只有查询向量最初移动到 GPU 内存，以及一个小的候选集（通常每个查询少于 1KB）在 ① 之后返回给 CPU。该设计通过优雅降级确保搜索质量：如果只有最后阶段运行，系统就像传统的贪婪搜索一样运作，而当所有阶段协同工作时会带来加速。</p></li></ul><h3 id="_4-2-理解性能" tabindex="-1"><a class="header-anchor" href="#_4-2-理解性能"><span>4.2. 理解性能</span></a></h3><ul><li><p>我们的方法通过两个方面展示了有效性。首先，GPU 阶段 ① 可以显着降低后续 CPU 阶段 ② ③ 的搜索复杂度。其次，GPU 的大规模并行处理能力对于我们的方法至关重要，因为它们使得能够进行高效的图遍历，确保多阶段开销不会损害其优势。我们通过以下性能分析验证这些主张。</p></li><li><p><strong>降低的搜索复杂度。</strong> 我们的方法建立在一个简单但强大的观察之上：当基于图的 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 搜索以一些已知的事实结果开始时，它会变得更加高效。为了衡量这种效果，我们使用每个节点 32 个邻居的 HNSW 进行了实验，比较了使用或不使用部分真实结果初始化的搜索。具体来说，对于前者，我们通过结合 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>τ</mi></mrow><annotation encoding="application/x-tex">\\tau</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 个已知的正确结果和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>e</mi><mi>f</mi><mo>−</mo><mi>τ</mi></mrow><annotation encoding="application/x-tex">ef - \\tau</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 个随机选择的节点来构建大小为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>e</mi><mi>f</mi></mrow><annotation encoding="application/x-tex">ef</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span></span></span></span> 的初始搜索候选项。</p></li><li><p>图 3 展示了这种方法的巨大好处。当以 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mi>τ</mi><mrow><mi>e</mi><mi>f</mi></mrow></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>4</mn></mfrac><mo separator="true">,</mo><mfrac><mn>1</mn><mn>8</mn></mfrac></mrow><annotation encoding="application/x-tex">\\frac{\\tau}{ef} = \\frac{1}{4}, \\frac{1}{8}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1765em;vertical-align:-0.4811em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.10764em;">f</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4811em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">8</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span> 开始时，与没有真实结果的搜索相比，该搜索仅需要 39.9% 和 48.1% 的距离计算即可达到 0.90 的召回率。这种改进发生是因为搜索立即集中在图的有希望区域，避免了在探索不太相关区域上的浪费精力。我们在不同的数据集上观察到了类似的改进，显示了其通用性。在提议的设计中，前两个阶段 ① ② 利用 GPU 的并行处理能力快速识别高质量的邻居，这些邻居充当近似真实结果，加速最后阶段 ③。</p></li><li><p><img src="'+u+'" alt="image3" loading="lazy"></p></li><li><p><img src="'+x+'" alt="image4" loading="lazy"></p></li><li><p>这种好处只有在识别出足够比例的真实邻居时才会显现。我们将<em>加速阈值</em>定义为实现有意义加速（例如 2 倍）所需的最小比率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mi>τ</mi><mrow><mi>e</mi><mi>f</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{\\tau}{ef}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1765em;vertical-align:-0.4811em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.10764em;">f</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4811em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>。如图 4 所示，此阈值因数据集而异，通常需要 15-21% 的真实结果。这个最低阈值要求指导了我们的系统设计——我们采用图采样和向量降维来最大化可以适应有限 GPU 内存的子图大小。</p></li><li><p><strong>阶段细分。</strong> 跨阶段距离计算的细分揭示了为什么 GPU 加速对我们的设计至关重要（表 1）。虽然基线 HNSW 需要 668.8 次计算才能达到 0.9 的召回率，但我们的方法将其工作负载分配到三个阶段：初始 GPU 阶段的 574.2 次计算，随后的两个 CPU 阶段分别为 44.2 和 189.0 次计算。CPU 执行的部分在 ② ③ 上总计 233.2 次计算，比基线小 3.3 倍，这是我们加速的关键。虽然多阶段总共涉及更多计算，但 GPU 的并行处理能力有效地处理了 ① 增加的工作负载。具体来说，我们测量 CPU 和 GPU 上的向量到向量距离计算，GPU 能够处理比单个 CPU 核心多 82 倍的计算。我们通过分批处理查询并跨 CPU 和 GPU 阶段流水线执行来进一步优化系统吞吐量。</p></li><li><p><img src="'+w+'" alt="table1" loading="lazy"></p></li></ul><h3 id="_4-3-方法细节" tabindex="-1"><a class="header-anchor" href="#_4-3-方法细节"><span>4.3. 方法细节</span></a></h3><ul><li><p><strong>子图管理。</strong> 子图表示采用修改后的压缩稀疏行（CSR）格式，优化内存使用，同时保持子图和全图之间的有效映射。我们不是完全移除采样期间排除的节点，而是保留它们在 CSR 结构中的存在，但移除它们的连接信息和嵌入向量。这些节点用零出度表示，任何入边都被修剪。这种设计使得 GPU 上的数据结构有一点冗余（这些零度节点），但是，它避免了子图和全图表示之间节点 ID 映射的计算开销，从而提高了 CPU 性能。</p></li><li><p><strong>已访问表管理。</strong> 我们的 GPU 内核利用布隆过滤器跟踪已访问节点，过滤器状态存储在共享内存中。这种设计消除了动态内存分配的需要，并减少了 DRAM 访问开销。虽然布隆过滤器已知会产生假阳性——错误地将未访问的节点标记为已访问——但这个限制并不损害我们系统的正确性。我们的多阶段处理流水线通过在 CPU 端精炼 GPU 结果来确保准确性，在 CPU 端任何假阳性节点都会被适当地重新访问。</p></li></ul><h2 id="_5-快速入口选择" tabindex="-1"><a class="header-anchor" href="#_5-快速入口选择"><span>5. 快速入口选择</span></a></h2><ul><li><p>在基于图的 ANNS 中，搜索在执行图遍历之前从入口点开始。这些入口点可以是预定义的节点（Malkov &amp; Yashunin, 2020）或随机选择的点（Fu et al., 2019）。我们引入了快速入口选择（FES），这是一种为 GPU 执行优化的新方法，在 §4 之前运行。FES 采用类似 GEMM 的高密度距离计算来提高入口点质量而不影响搜索速度，从而提高整体系统效率。</p></li><li><p><strong>计算密度。</strong> 我们首先根据 roofline 性能模型（Williams et al., 2009）检查计算密度。给定向量维度 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>d</mi></mrow><annotation encoding="application/x-tex">d</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">d</span></span></span></span>，我们有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi></mrow><annotation encoding="application/x-tex">m</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span></span></span></span> 个查询向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>∈</mo><msup><mi mathvariant="double-struck">R</mi><mrow><mi>m</mi><mo>×</mo><mi>d</mi></mrow></msup></mrow><annotation encoding="application/x-tex">Q \\in \\mathbb{R}^{m \\times d}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 个入口向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi><mi>V</mi><mo>∈</mo><msup><mi mathvariant="double-struck">R</mi><mrow><mi>n</mi><mo>×</mo><mi>d</mi></mrow></msup></mrow><annotation encoding="application/x-tex">EV \\in \\mathbb{R}^{n \\times d}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">E</span><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span></span>。如表 2 所列，直接的蛮力方法计算每个查询和入口向量之间的距离，产生一个 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi><mo>×</mo><mi>n</mi></mrow><annotation encoding="application/x-tex">m \\times n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">m</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 矩阵 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>D</mi></mrow><annotation encoding="application/x-tex">D</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">D</span></span></span></span>，其中每个元素代表一个查询向量和一个入口向量之间的距离。将平方欧几里得距离计算 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>e</mi><mi>u</mi><mi>c</mi><mi>l</mi><mi>i</mi><mi>d</mi><mi>e</mi><mi>a</mi><mi>n</mi><mo stretchy="false">(</mo><msub><mi>x</mi><mn>1</mn></msub><mo separator="true">,</mo><msub><mi>x</mi><mn>2</mn></msub><mo stretchy="false">)</mo><mo>=</mo><mo stretchy="false">(</mo><msub><mi>x</mi><mn>1</mn></msub><mo>−</mo><msub><mi>x</mi><mn>2</mn></msub><msup><mo stretchy="false">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">euclidean(x_1, x_2) = (x_1 - x_2)^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">e</span><span class="mord mathnormal">u</span><span class="mord mathnormal">c</span><span class="mord mathnormal" style="margin-right:0.01968em;">l</span><span class="mord mathnormal">i</span><span class="mord mathnormal">d</span><span class="mord mathnormal">e</span><span class="mord mathnormal">an</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 视为单次计算，入口阶段涉及 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi><mi>n</mi><mi>d</mi></mrow><annotation encoding="application/x-tex">mnd</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">mn</span><span class="mord mathnormal">d</span></span></span></span> 次计算和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi><mi>d</mi><mo>+</mo><mi>n</mi><mi>d</mi></mrow><annotation encoding="application/x-tex">md+nd</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">m</span><span class="mord mathnormal">d</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">n</span><span class="mord mathnormal">d</span></span></span></span> 次内存读取，计算与内存访问的比率为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mi>m</mi><mi>n</mi></mrow><mrow><mi>m</mi><mo>+</mo><mi>n</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{mn}{m+n}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0987em;vertical-align:-0.4033em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">mn</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4033em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>，即计算密度。</p></li><li><p><img src="'+y+'" alt="table2" loading="lazy"></p></li><li><p>在邻居扩展期间（算法 1 中的第 6-10 行），计算相同的距离 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>D</mi></mrow><annotation encoding="application/x-tex">D</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">D</span></span></span></span> 需要 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi><mi>d</mi><mo>+</mo><mi>m</mi><mi>n</mi><mi>d</mi></mrow><annotation encoding="application/x-tex">md+mnd</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">m</span><span class="mord mathnormal">d</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">mn</span><span class="mord mathnormal">d</span></span></span></span> 次内存读取查询向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 和邻居向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mo>∈</mo><msup><mi mathvariant="double-struck">R</mi><mrow><mi>m</mi><mo>×</mo><mi>n</mi><mo>×</mo><mi>d</mi></mrow></msup></mrow><annotation encoding="application/x-tex">V \\in \\mathbb{R}^{m \\times n \\times d}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight">n</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span></span>，其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi></mrow><annotation encoding="application/x-tex">m</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span></span></span></span> 个查询中的每一个都有不同的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 个邻居。这产生了 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mi>n</mi><mrow><mn>1</mn><mo>+</mo><mi>n</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{n}{1+n}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0987em;vertical-align:-0.4033em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4033em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span> 的计算密度，随着 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>m</mi></mrow><annotation encoding="application/x-tex">m</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span></span></span></span> 的增加，显着低于 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mi>m</mi><mi>n</mi></mrow><mrow><mi>m</mi><mo>+</mo><mi>n</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{mn}{m+n}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0987em;vertical-align:-0.4033em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">mn</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4033em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>。在图构建过程中，即 local-join，也报告了类似的情况（Dong et al., 2011）。这一观察激励我们探索能够保持高计算密度同时减少有效搜索空间的新方法。</p></li><li><p><strong>基于聚类的选择。</strong> 受 IVF 的启发，我们提出了一种简化且桶对齐的方法，优化用于入口点选择。我们的方法将入口向量组织成少量粗略的簇 (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span></span></span></span>)，从而在 GPU 上实现高效的类似 GEMM 的计算。与 IVF 不同（IVF 通常采用数千个大小差异很大的桶），我们的方法特意使用少量粗略簇 (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>&lt;</mo><mo>&lt;</mo></mrow><annotation encoding="application/x-tex">r &lt;&lt;</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;&lt;</span></span></span></span> IVF 桶)。对于查询 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 和入口向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi><mi>V</mi></mrow><annotation encoding="application/x-tex">EV</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">E</span><span class="mord mathnormal" style="margin-right:0.22222em;">V</span></span></span></span>，我们的方法根据它们与簇质心的接近程度将查询动态路由到适当的簇。当一组查询 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>Q</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">Q_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 被分配给簇 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 时，它会激活该簇内的入口向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi><msub><mi>V</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">EV_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">E</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 进行距离计算。其他簇中的入口向量被认为太远，被排除在特定查询的距离计算之外。</p></li><li><p><strong>无分配和平铺 FES。</strong> 最后的挑战是高效实施 FES。直接的实现可能会在执行距离计算之前提取 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>Q</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">Q_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi><msub><mi>V</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">EV_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">E</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.22222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。然而，这种方法可能导致内存分配和复制，可能会降低性能。为了克服这个限制，我们开发了一个无分配和平铺 GPU 内核，如算法 2 所示。算法首先将计算分布在多个 GPU 块上（第 3 行），每个块处理查询和入口向量的一个子集。在每个块内，算法静态声明两个共享内存块来存储部分查询和入口向量（第 4 行）。接下来，每个块以平铺方式迭代入口向量和查询（第 7, 12 行）。这种平铺方法对于性能至关重要，因为它最大化了内存读取和数据重用。</p></li><li><p><img src="'+v+'" alt="algo2" loading="lazy"></p></li><li><p>由于仅使用对应于特定入口向量的查询进行距离计算，非活动查询（那些在其他块中处理的）被跳过（第 9-11 行）。这种选择性计算减少了不必要的内存加载和计算。对于匹配的查询，算法计算查询和入口向量之间的部分距离（第 14 行）。最后，这些部分距离被累积到最终距离数组中（第 15 行），完成当前块的计算。结果是一个高度优化的距离计算。像 GEMM 一样，该算法利用多级并行性，它将计算划分为图块并在这些较小的图块上执行距离计算。</p></li><li><p>请注意，这种平铺计算模式，以簇为中心而不是以查询为中心，是专门为入口点选择量身定制的。我们将每个簇分配给一个 GPU 块，这对于传统的 IVF 工作负载来说是低效的，原因有两个。首先，大量的 IVF 桶（通常数千个）在由 GPU 块处理时会导致显着的读取放大（第 3 行）。其次，IVF 桶大小的高方差会导致负载不平衡，因为整个内核必须等待最大的桶完成处理（第 16 行）。</p></li><li><p><strong>复杂性分析。</strong> 如表 2 所列，图遍历的距离计算具有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><mi>m</mi><mi>n</mi><mi>d</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(mnd)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathnormal">mn</span><span class="mord mathnormal">d</span><span class="mclose">)</span></span></span></span> 的时间复杂度。对于具有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span></span></span></span> 个簇的 FES，时间复杂度为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><mfrac><mrow><mi>m</mi><mi>n</mi><mi>d</mi></mrow><mi>r</mi></mfrac><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(\\frac{mnd}{r})</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2251em;vertical-align:-0.345em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8801em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.02778em;">r</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">mn</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose">)</span></span></span></span>，因为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 个向量分布到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span></span></span></span> 个单元，其中每个查询仅执行 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mi>n</mi><mi>r</mi></mfrac></mrow><annotation encoding="application/x-tex">\\frac{n}{r}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0404em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.02778em;">r</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span> 次计算。当使用 1 个块时，FES 恢复为蛮力；当只有一个查询要处理时，FES 具有与图遍历相同的复杂性。我们将 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">r</span></span></span></span> 设置为 32 以匹配 GPU 的 warp 大小，同时获得更高的计算密度。</p></li></ul><h2 id="_6-评估" tabindex="-1"><a class="header-anchor" href="#_6-评估"><span>6. 评估</span></a></h2><h3 id="_6-1-实验设置" tabindex="-1"><a class="header-anchor" href="#_6-1-实验设置"><span>6.1. 实验设置</span></a></h3><ul><li><p>实验是在配备 Intel Xeon Platinum 8369B CPU 和 NVIDIA A10 GPU (24 GB) 的云虚拟机上进行的。我们分配了 32 个 vCPU（相当于 16 个 OpenMP 线程）进行评估。在 CPU 和 GPU 上均使用单精度 float32 进行距离计算，并且使用高达 AVX2 的 SIMD 指令，遵循开源社区的性能调优指南。</p></li><li><p><strong>数据集。</strong> 我们使用表 3 中列出的四个 1 亿规模数据集，DEEP (Babenko &amp; Lempitsky, 2016)，T2I (Yandex, 2021)，WIKI 和 LAION (Schuhmann et al., 2022)，代表超出典型 GPU 内存容量的中等和高维数据。对于 WIKI 数据集，我们通过从英文维基百科采样 1 亿段落并使用 BGE (Xiao et al., 2023) 模型生成嵌入来构建它，该模型作为 LlamaIndex (Liu, 2022) 框架中的默认嵌入方法。我们也使用相同数据集的较小 100 万子集（例如，DEEP-1M）进行分析，因为它们的原始大小可能会带来挑战。</p></li><li><p><img src="'+k+'" alt="table3" loading="lazy"></p></li><li><p><strong>基线。</strong> 我们将 PilotANN 与以下最先进的方法进行比较：</p><ul><li><em>HNSW</em> (Malkov &amp; Yashunin, 2020) 是以其稳健性能而闻名的行业标准解决方案。我们评估来自 FAISS (Douze et al., 2024) 1.8.0 的 CPU 实现。为了确保公平比较，PilotANN 利用与 FAISS 相同的训练图索引，而不改变训练算法。</li><li><em>RUMMY</em> (Zhang et al., 2024) 是一种最近的基于 IVF（粗略聚类）的方法，旨在解决类似的挑战。它也专注于解决 ANNS 中的 GPU 内存限制。</li><li><em>CAGRA</em> (Ootomo et al., 2023)，NVIDIA 的 ANNS 算法，作为额外的基线进行了评估，但在处理我们的数据集时遇到了 GPU 内存边界。</li></ul></li><li><p><strong>指标。</strong> 我们关注召回率作为我们的主要指标，测量为：recall@k = <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mi mathvariant="normal">∣</mi><msub><mtext>retrieved</mtext><mi>k</mi></msub><mo>∩</mo><msub><mtext>groundtruth</mtext><mi>k</mi></msub><mi mathvariant="normal">∣</mi></mrow><mi>k</mi></mfrac></mrow><annotation encoding="application/x-tex">\\frac{|\\text{retrieved}_k \\cap \\text{groundtruth}_k|}{k}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.3661em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.0211em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.03148em;">k</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.4961em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∣</span><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">retrieved</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.03148em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span><span class="mbin mtight">∩</span><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">groundtruth</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2302em;"><span style="top:-2.2341em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.03148em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2659em;"><span></span></span></span></span></span></span><span class="mord mtight">∣</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>。特别是，我们通过召回率-吞吐量曲线评估 PilotANN 的有效性，展示准确性如何与计算性能进行权衡。</p></li></ul><h3 id="_6-2-整体性能" tabindex="-1"><a class="header-anchor" href="#_6-2-整体性能"><span>6.2. 整体性能</span></a></h3><ul><li><p>PilotANN 在所有场景中均表现出相对于基线的显着性能改进。</p></li><li><p><strong>整体。</strong> 图 5 展示了与不同大规模数据集上的 <em>HNSW-CPU</em> 相比，PilotANN 的吞吐量改进。对于 96 维 DEEP 数据集，我们的方法实现了相对于基线的 3.9 倍加速。对于其他数据集，性能增益甚至更显着，显示出 5.1 - 5.4 倍的加速，随着向量维度的增加，好处变得更加明显。<em>RUMMY</em> 在所有场景中都慢于 <em>HNSW-CPU</em>，因为 IVF 方法（<em>RUMMY</em> 所利用的）固有地需要比 HNSW 更多的距离计算。对于 top-100 搜索也观察到了类似的好处（由于页面限制省略）。值得注意的是，T2I 是一个已知的困难评估 (Simhadri et al., 2022)，尽管没有专门针对该数据集进行优化，我们的方法仍然提供了显着的加速。</p></li><li><p><img src="'+b+'" alt="image5" loading="lazy"></p></li><li><p><strong>成本效益。</strong> 尽管基于 GPU 的平台（2.81 美元/小时）比纯 CPU 解决方案（1.69 美元/小时）的成本显着更高，但我们实现了显着的成本效益：在吞吐量每美元方面，DEEP 为 2.3 倍，T2I、WIKI 和 LAION 为 3.0 - 3.2 倍，如表 4 所示。这表明 PilotANN 在更高维 ANNS 方面表现出色。鉴于提高 CPU 能力的困难，PilotANN 为增强 ANNS 处理能力提供了一个实用的解决方案。</p></li><li><p><img src="'+M+'" alt="table4" loading="lazy"></p></li><li><p><strong>CAGRA-UVM。</strong> 图 6 说明了 PilotANN 与 CAGRA 的比较。<em>CAGRA</em> 无法扩展超出 GPU 内存限制（即我们的数据集），我们将其内存分配切换为 <code>cudaMallocManaged</code> (NVIDIA, 2020)。这启用了统一虚拟内存（UVM），导致当发生越界访问时 CPU 和 GPU 之间的内存复制。对于适合 GPU 内存的数据集，CAGRA 获得了相对于基线高达 32 倍的加速，而 PilotANN 表现略差，因为我们的内核设计用于处理子图，导致额外的开销。当数据集超过 GPU 内存时，UVM 使用导致低效的 CPU-GPU 数据传输，导致 <em>CAGRA</em> 变慢，落后于纯 CPU 方法。相比之下，PilotANN 展示了处理不断增长的数据集的可扩展性。</p></li><li><p><img src="'+N+'" alt="image6" loading="lazy"></p></li><li><p><strong>最小 GPU 内存需求。</strong> 我们通过确定实现加速所需的最小 GPU 内存来评估 PilotANN 的可扩展性。我们分配高达 81% 的可用 GPU 内存（表 3）用于图索引和向量，保留其余部分用于查询处理期间的动态分配（例如，查询向量和候选集）。使用 LAION 数据集的实验证明了 PilotANN 出色的可扩展性。使用 19.4 GB GPU 内存，我们在处理比分配的内存大 14.9 倍的数据集时实现了 4.8 倍的吞吐量加速。随着我们将 GPU 内存减少到 9.7 GB（数据集大 29.7 倍），系统仍保持 2.6 倍的加速，如图 7 所示。由于我们的方法与量化技术互补，未来的集成可以实现更大的可扩展性。</p></li><li><p><img src="'+P+'" alt="image7" loading="lazy"></p></li></ul><h3 id="_6-3-组件分析" tabindex="-1"><a class="header-anchor" href="#_6-3-组件分析"><span>6.3. 组件分析</span></a></h3><ul><li><p><strong>消融研究。</strong> 我们在 LAION 数据集上进行了消融研究，以评估 CPU-GPU 流水线、快速入口选择和多阶段处理。如表 5 所示，我们依次移除每个组件，发现所有组件都对系统性能做出了积极贡献。其中，GPU 领航阶段展示了最显着的影响，改进了 276%。即使移除了所有组件，只留下一个朴素的纯 CPU 贪婪搜索实现，由于我们手动优化的 AVX2 实现，PilotANN 仍保持 1.27 倍的加速。</p></li><li><p>其他分析可以在附录 §A 中找到。</p></li><li><p><img src="'+U+'" alt="table5" loading="lazy"></p></li></ul><h2 id="_7-相关工作" tabindex="-1"><a class="header-anchor" href="#_7-相关工作"><span>7. 相关工作</span></a></h2><h3 id="_7-1-大规模-anns" tabindex="-1"><a class="header-anchor" href="#_7-1-大规模-anns"><span>7.1. 大规模 ANNS</span></a></h3><ul><li>之前的 ANNS 研究主要集中在索引结构和数据编码优化上，倒排多索引（IMI）(Babenko &amp; Lempitsky, 2015) 通过多码本量化增强了空间划分，而 PQFastScan (André et al., 2016) 通过 SIMD 和缓存感知优化提高了性能。FAISS (Douze et al., 2024) 是一个广泛采用的 ANNS 库，可有效地扩展到 RAM 容量，但 GPU 支持有限。DiskANN (Jayaram Subramanya et al., 2019) 和 SPANN (Chen et al., 2021) 引入了用于十亿级数据集的新颖基于磁盘的索引，解决了与我们的工作不同但相关的内存层次结构挑战。PilotANN 与量化和基于磁盘的方法正交，表明未来有可能整合这两种方法。</li></ul><h3 id="_7-2-gpu-加速-anns" tabindex="-1"><a class="header-anchor" href="#_7-2-gpu-加速-anns"><span>7.2. GPU 加速 ANNS</span></a></h3><ul><li>几种方法利用 GPU 进行 ANNS 加速。RUMMY (Zhang et al., 2024) 实现了针对基于 IVF 的搜索的 CPU-GPU 流水线，尽管这种策略对于基于图的索引是次优的。SONG (Zhao et al., 2020) 和 CAGRA (Ootomo et al., 2023) 通过 GPU 并行化实现了显着的加速，但它们的方法受到 GPU 内存容量的限制。BANG (Karthik et al., 2024) 使用混合 CPU-GPU 处理处理了十亿级数据集，但缺乏 CPU 基线比较。相比之下，PilotANN 提出了一个内存受限的 GPU 加速框架，该框架有效地利用了商用 GPU，同时克服了它们的内存限制。此外，PilotANN 还保持了与现有 CPU 系统的完全兼容性，并在不损害搜索精度或需要高端 GPU 硬件的情况下实现了显着的加速。</li></ul><h2 id="_8-结论" tabindex="-1"><a class="header-anchor" href="#_8-结论"><span>8. 结论</span></a></h2><ul><li>这项工作引入了一种新颖的基于图的 ANNS 系统，该系统有效地利用 CPU 和 GPU 来处理新兴的 ANNS 工作负载。通过将 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 搜索分解为多阶段 CPU-GPU 流水线并采用高效的入口选择，我们的系统实现了相对于现有纯 CPU 方法的显着性能改进。</li></ul><h3 id="影响陈述" tabindex="-1"><a class="header-anchor" href="#影响陈述"><span>影响陈述</span></a></h3><ul><li>我们提出的 PilotANN 系统的有效性和效率通过仅使用单个商用 GPU 实现具有竞争力的性能，使高性能最近邻搜索大众化。我们的设计显着降低了计算开销，使具有有限计算资源的研究人员和组织能够获得高级搜索能力。与需要昂贵高端 GPU 的现有解决方案不同，我们的方法能够在普通硬件设置上高效部署 ANNS，同时保持搜索精度。这项工作有助于可持续的 AI 基础设施开发，并支持 ANNS 技术在各种应用中的更广泛采用，特别是对于最近的生成式 AI。</li></ul>',37))])}const C=i(_,[["render",z]]),S=JSON.parse('{"path":"/article/reading/A-%E5%90%91%E9%87%8F%E6%95%B0%E6%8D%AE%E5%BA%93/T-PilotANN/PilotANN.html","title":"PilotANN: 针对向量搜索的内存受限 GPU 加速","lang":"zh-CN","frontmatter":{"date":"2025-03-27T00:00:00.000Z","category":"论文阅读","tag":["Vector Database","ANNS","GPU Acceleration","Hybrid Systems"],"feed":false,"seo":false,"head":[]},"headers":[{"level":2,"title":"摘要","slug":"摘要","link":"#摘要","children":[]},{"level":2,"title":"1. 引言","slug":"_1-引言","link":"#_1-引言","children":[]},{"level":2,"title":"2. 背景","slug":"_2-背景","link":"#_2-背景","children":[{"level":3,"title":"2.1. ANNS 方法","slug":"_2-1-anns-方法","link":"#_2-1-anns-方法","children":[]},{"level":3,"title":"2.2. 重温图遍历","slug":"_2-2-重温图遍历","link":"#_2-2-重温图遍历","children":[]}]},{"level":2,"title":"3. 概述","slug":"_3-概述","link":"#_3-概述","children":[]},{"level":2,"title":"4. GPU 领航：一种混合方法","slug":"_4-gpu-领航-一种混合方法","link":"#_4-gpu-领航-一种混合方法","children":[{"level":3,"title":"4.1. ANNS 的多阶段处理","slug":"_4-1-anns-的多阶段处理","link":"#_4-1-anns-的多阶段处理","children":[]},{"level":3,"title":"4.2. 理解性能","slug":"_4-2-理解性能","link":"#_4-2-理解性能","children":[]},{"level":3,"title":"4.3. 方法细节","slug":"_4-3-方法细节","link":"#_4-3-方法细节","children":[]}]},{"level":2,"title":"5. 快速入口选择","slug":"_5-快速入口选择","link":"#_5-快速入口选择","children":[]},{"level":2,"title":"6. 评估","slug":"_6-评估","link":"#_6-评估","children":[{"level":3,"title":"6.1. 实验设置","slug":"_6-1-实验设置","link":"#_6-1-实验设置","children":[]},{"level":3,"title":"6.2. 整体性能","slug":"_6-2-整体性能","link":"#_6-2-整体性能","children":[]},{"level":3,"title":"6.3. 组件分析","slug":"_6-3-组件分析","link":"#_6-3-组件分析","children":[]}]},{"level":2,"title":"7. 相关工作","slug":"_7-相关工作","link":"#_7-相关工作","children":[{"level":3,"title":"7.1. 大规模 ANNS","slug":"_7-1-大规模-anns","link":"#_7-1-大规模-anns","children":[]},{"level":3,"title":"7.2. GPU 加速 ANNS","slug":"_7-2-gpu-加速-anns","link":"#_7-2-gpu-加速-anns","children":[]}]},{"level":2,"title":"8. 结论","slug":"_8-结论","link":"#_8-结论","children":[{"level":3,"title":"影响陈述","slug":"影响陈述","link":"#影响陈述","children":[]}]}],"git":{"createdTime":1787540590000,"updatedTime":1787540590000,"contributors":[{"name":"z-ben","username":"z-ben","email":"12800262+z-ben@user.noreply.gitee.com","commits":1,"url":"https://github.com/z-ben"}]},"readingTime":{"minutes":28.81,"words":8642},"filePathRelative":"article/reading/A-向量数据库/T-PilotANN/PilotANN.md","localizedDate":"2025年3月27日"}');export{C as comp,S as data};
